#!/usr/bin/env bash
# The README's diagrams (docs/assets/*.svg) are generated by their scripts (docs/assets/*.py). A
# generated file that is also committed must match its source (AGENTS.md: derived values have one
# source of truth), so a hand edit to an SVG, or a generator change without regenerating, fails here.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
failures=0
found=0
for gen in "$ROOT"/docs/assets/*.py; do
	[ -e "$gen" ] || continue
	found=$((found + 1))
	if out="$(python3 "$gen" --check 2>&1)"; then
		printf 'ok - %s\n' "$out"
	else
		printf 'not ok - %s\n' "$out" >&2
		failures=$((failures + 1))
	fi
done
if [ "$found" -eq 0 ]; then
	printf 'not ok - no diagram generator under docs/assets/\n' >&2
	exit 1
fi
[ "$failures" -eq 0 ]
